class Solution {
public:
    int partitionArray(std::vector<int>& nums, int k) {
        std::sort(nums.begin(), nums.end());
        int ans = 1, anchor = nums[0];
        for (size_t i = 1; i < nums.size(); ++i) {
            if (nums[i] - anchor > k) {
                ans++;
                anchor = nums[i];
            }
        }
        return ans;
    }
};

class Solution {
    public int partitionArray(int[] nums, int k) {
        java.util.Arrays.sort(nums);
        int ans = 1;
        int anchor = nums[0];
        for (int i = 1; i < nums.length; i++) {
            if (nums[i] - anchor > k) {
                ans++;
                anchor = nums[i];
            }
        }
        return ans;
    }
}

var partitionArray = function(nums, k) {
    nums.sort((a, b) => a - b);
    let ans = 1;
    let anchor = nums[0];
    for (let i = 1; i < nums.length; i++) {
        if (nums[i] - anchor > k) {
            ans++;
            anchor = nums[i];
        }
    }
    return ans;
};
